{
  "name": "管式炉CVD配方控制组件",
  "name_en": "Tube Furnace CVD Recipe Controller",
  "manufacturer": "",
  "description": "用于管式炉CVD系统的非物理配方执行软件组件。它根据预定义步骤协调炉温、质量流量控制器和压力相关参数，支持设备初始化、过程执行、参数轮询与运行日志记录，适合自动化工艺流程管理。",
  "description_en": "A non-physical recipe execution software component for a tube furnace CVD system. It coordinates furnace temperature, mass flow controller settings, and pressure-related parameters according to predefined steps, and supports device initialization, process execution, parameter polling, and run logging for automated process management.",
  "actions": [
    {
      "action_name": "auto-run",
      "description": "执行整套工艺配方，按步骤设置炉温和气体流量，并在各步骤中等待温度接近设定值及保持规定时间。",
      "description_en": "Run the full process recipe by stepwise setting furnace temperature and gas flow rates, then waiting for temperature to approach the setpoint and holding each step for the specified time."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化并验证配方所需设备的通信与可用状态。",
      "description_en": "Initialize the recipe and verify communication and availability of the required devices."
    },
    {
      "action_name": "auto-logging",
      "description": "按设定频率记录运行参数并写入日志文件。",
      "description_en": "Log operating parameters at a specified frequency and write them to a log file."
    },
    {
      "action_name": "auto-poll",
      "description": "轮询相关设备，读取当前运行参数并汇总返回。",
      "description_en": "Poll the associated devices to read current operating parameters and return them in a combined result."
    }
  ],
  "tag_hints": [
    "tube furnace CVD",
    "recipe execution",
    "process sequencing",
    "temperature and gas-flow coordination",
    "MFC integration",
    "process logging",
    "device polling"
  ]
}

